import { Order } from './types';

export interface OrderPosition { createdAt: string; id: string }

function compare(a: OrderPosition, b: OrderPosition): number {
  return a.createdAt < b.createdAt ? -1 : a.createdAt > b.createdAt ? 1 : a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
}

export class OrderRepository {
  constructor(private readonly rows: Order[]) {}
  // Returns a new sorted array of the tenant's orders (filtering happens before the
  // cursor is applied). If `after` is given, only orders strictly after that
  // (createdAt, id) position are returned, even if no such row exists.
  list(tenant: string, after?: OrderPosition): Order[] {
    return this.rows
      .filter(row => row.tenant === tenant && (after === undefined || compare(row, after) > 0))
      .sort(compare);
  }
}
EOF
